SELECT * FROM appointment
WHERE deleted = 0

    AND store_id = #{storeId}


    AND appointment_no = #{appointmentNo}


    AND customer_id = #{customerId}


    AND beautician_id = #{beauticianId}


    AND status = #{status}


    AND appointment_date >= #{startDate}


    AND appointment_date <= #{endDate}


    AND (customer_name LIKE CONCAT('%', #{keyword}, '%')
         OR customer_phone LIKE CONCAT('%', #{keyword}, '%')
         OR beautician_name LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM appointment
WHERE deleted = 0

    AND store_id = #{storeId}


    AND appointment_no = #{appointmentNo}


    AND customer_id = #{customerId}


    AND beautician_id = #{beauticianId}


    AND status = #{status}


    AND appointment_date >= #{startDate}


    AND appointment_date <= #{endDate}


    AND (customer_name LIKE CONCAT('%', #{keyword}, '%')
         OR customer_phone LIKE CONCAT('%', #{keyword}, '%')
         OR beautician_name LIKE CONCAT('%', #{keyword}, '%'))

SELECT * FROM appointment
WHERE deleted = 0
  AND beautician_id = #{beauticianId}
  AND appointment_date = #{date}
ORDER BY appointment_time ASC

SELECT * FROM appointment
WHERE deleted = 0
  AND appointment_date >= #{startDate}
  AND appointment_date <= #{endDate}
ORDER BY appointment_date ASC, appointment_time ASC

SELECT COUNT(*) FROM appointment
WHERE deleted = 0
  AND beautician_id = #{beauticianId}
  AND appointment_date = #{date}
  AND status NOT IN (5, 6)

      AND id != #{excludeId}

  AND (
      (appointment_time < #{endTime} AND end_time > #{startTime})
  )
